      out.write("    });\n");
      out.write("\n");
      out.write("    var reveals = document.querySelectorAll('.reveal');\n");
      out.write("    var observer = new IntersectionObserver(function (entries) {\n");
      out.write("        entries.forEach(function (entry) {\n");
      out.write("            if (entry.isIntersecting) { entry.target.classList.add('show'); }\n");
      out.write("        });\n");
      out.write("    }, { threshold: 0.12 });\n");
      out.write("    reveals.forEach(function (el) { observer.observe(el); });\n");
