      out.write("            var suffix = counter.getAttribute('data-suffix') || '';\n");
      out.write("            var current = 0;\n");
      out.write("            var increment = Math.ceil(target / 40);\n");
      out.write("            var interval = setInterval(function () {\n");
      out.write("                current += increment;\n");
      out.write("                if (current >= target) { current = target; clearInterval(interval); }\n");
      out.write("                counter.textContent = current + suffix;\n");
      out.write("            }, 30);\n");
      out.write("        });\n");
      out.write("    }\n");
      out.write("    var statsSection = document.querySelector('.stats-section');\n");
